import React from 'react';

import { useNavigate } from 'react-router-dom';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

import { getInterviewsList } from '../@services/interview.service';
import { IInterview } from '../@types/interview.types';
import { editInterview } from '../components/EditInterview';
import InterviewListItem from '../components/InterviewListItem';
import InterviewRun from '../components/InterviewRun';
import { getEmptyInterview } from '../resources/interview.empty';

const InterviewListPages: React.FC = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IInterview[]>([]);
  const authContext = React.useContext(AuthContext);

  const navigate = useNavigate();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getInterviewsList({});
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs data={[{ href: '/iv', text: 'Опросы', active: true }]} />

      <PohContainer>
        <PageHeader title="Опросы">
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={async () => {
              if (!authContext.user) return;
              const newInterview = await editInterview(getEmptyInterview(authContext.user));
              notificationHelper.success('Добавлено');
              setData((cur) => [...cur, newInterview]);
              navigate(`/iv/${newInterview.id}`);
            }}
          >
            Добавить
          </PohButton>
        </PageHeader>
        <div>
          <PohList
            flush
            data={data.map((interview) => {
              return {
                key: interview.id,
                action: true,
                onClick: (e) => {
                  if (e.altKey) {
                    return showModal({
                      children: (
                        <div style={{ width: '86vw' }}>
                          <InterviewRun id_interview={interview.id} />
                        </div>
                      ),
                    });
                  }
                  navigate(`/iv/${interview.id}`);
                },
                children: <InterviewListItem item={interview} />,
              };
            })}
          />
        </div>
      </PohContainer>
    </div>
  );
};

export default InterviewListPages;
